// Travkings logo (480×155 PNG, ~41 KB) embedded for the outgoing-mail signature. The app's
// signature HTML references it as <img src="cid:tk-sig-logo">; sendMail attaches these bytes
// as an INLINE attachment with that contentId so every mail client renders it (remote images
// get blocked; data: URIs are stripped by Gmail — cid inline is the one portable way).
export const SIG_LOGO_CID = 'tk-sig-logo';
export const SIG_LOGO_CONTENT_TYPE = 'image/png';
export const SIG_LOGO_B64 =
  '';
